 await call(ctx,{action:'line_receipt_dismiss',id:rows[0].id});await signedWebhook(ctx.env,[event]);assert.equal((await call(ctx,null,'?view=inbox')).value.line_receipts.length,0);assert.equal(meals.sql.prepare('SELECT source_cipher FROM meal_line_receipts').get().source_cipher,null);
