const externalWeekBody=(id='external-week-0001')=>({...proposalBody(id),external:{publisher:'DELISH',query:'夕飯'}});
const externalRecipeUrl=i=>'https://delishkitchen.tv/recipes/'+(166742173524427155n+BigInt(i));
const externalWeekHTML=(count=6)=>'<script type="application/ld+json">'+JSON.stringify({'@type':'ItemList',itemListElement:Array.from({length:count},(_,i)=>({name:'外部料理'+i,url:externalRecipeUrl(i)}))})+'</script>';
const externalRecipeHTML=(i,overrides={})=>'<script type="application/ld+json">'+JSON.stringify({'@type':'Recipe',name:'外部料理'+i,recipeYield:'2人分',totalTime:'PT'+(20+i)+'M',recipeIngredient:['ひき肉 200g','塩 お好みで'],recipeInstructions:['出典の手順で焼く'],...overrides})+'</script>';
function externalFetch(counter,options={}){return async(url,init)=>{const u=String(url);if(u.includes('/search?')){counter.search++;return new Response(externalWeekHTML(options.count??6),{headers:{'content-type':'text/html'}});}if(u.includes('delishkitchen.tv/recipes/')){counter.imports++;const i=Number(BigInt(new URL(u).pathname.split('/').pop())-166742173524427155n);if(options.fail) return new Response('',{status:403});return new Response(externalRecipeHTML(i,options.unknown?{totalTime:undefined,recipeYield:'不明',recipeIngredient:['肉 約200g','塩 適量']}:{}),{headers:{'content-type':'text/html'}});}counter.ai++;const prompt=JSON.parse(init.body),candidates=JSON.parse(prompt.contents[0].parts[0].text).candidates;counter.prompt=JSON.stringify(prompt);return options.aiResponse?options.aiResponse(candidates):aiResponse(candidates.slice(0,5).map(c=>c.id));};}
